UPDATE public.source_chunks sc SET is_active=true WHERE EXISTS (SELECT 1 FROM public.claim_chunks cc JOIN public.claims c ON c.id=cc.claim_id WHERE cc.chunk_id=sc.id AND c.review_status='approved' AND c.approval_origin='corpus_evidence_review');
UPDATE public.source_chunks sc SET is_active=false WHERE NOT EXISTS (SELECT 1 FROM public.claim_chunks cc JOIN public.claims c ON c.id=cc.claim_id WHERE cc.chunk_id=sc.id AND c.review_status='approved' AND c.approval_origin='corpus_evidence_review');
